UIShieldSparkGroup=function(game){Phaser.Group.call(this,game,null);this.boltGroup=this.game.add.group(this);for(var i=0;i<UIConstants.SHIELD_SPARK_BOLT_POOL_SIZE;++i){this.boltGroup.add(new UIShieldSparkBoltImage(game));}this.emitter=this.add(new UIShieldSparkEmitter(game));this.log=Log.create('UIShieldSparkGroup');this.exists=false;this.visible=false;};UIShieldSparkGroup.prototype=Object.create(Phaser.Group.prototype);UIShieldSparkGroup.prototype.constructor=UIShieldSparkGroup;UIShieldSparkGroup.prototype.update=function(){if(!this.exists){return;}Phaser.Group.prototype.update.call(this);if(this.countLiving()<=1&&this.boltGroup.countLiving()==0){this.exists=false;this.visible=false;}};UIShieldSparkGroup.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Group.prototype.postUpdate.call(this);};UIShieldSparkGroup.prototype.emit=function(tank,position){this.exists=true;this.visible=true;var boltImage=this.boltGroup.getFirstExists(false);var rotation=Phaser.Math.angleBetween(tank.getX(),tank.getY(),position.x,position.y);if(boltImage){boltImage.spawn(UIUtils.mpx(position.x),UIUtils.mpx(position.y),rotation);}else{}this.emitter.emit(UIUtils.mpx(position.x),UIUtils.mpx(position.y),rotation);};UIShieldSparkGroup.prototype.retire=function(){this.exists=false;this.visible=false;this.emitter.retire();this.boltGroup.callAll('retire');};